      )

economy_rulesets_draft_unpublished.value:
"economy_rulesets"."status" <> 'draft' OR (
        "economy_rulesets"."published_at" IS NULL AND "economy_rulesets"."published_by" IS NULL AND "economy_rulesets"."cancelled_at" IS NULL
      )

wallet_transactions_admin_attributed.value:
"wallet_transactions"."entry_type" <> 'admin_adjustment' or (
        "wallet_transactions"."actor_user_id" is not null and "wallet_transactions"."reason" is not null and length(btrim("wallet_transactions"."reason")) > 0
      )

wallet_transactions_source_complete.value:
("wallet_transactions"."source_type" is null and "wallet_transactions"."source_id" is null) or (
        "wallet_transactions"."source_type" ~ '^[a-z][a-z0-9_]{1,63}$' and "wallet_transactions"."source_id" is not null and length(btrim("wallet_transactions"."source_id")) > 0
      )
